<main class="dashboard-container" aria-labelledby="audit-title"><div class="page-heading"><div><div class="page-eyebrow">Security / accountability</div><h1 id="audit-title">Audit logs</h1><p class="text-muted mb-0">Review recent security, clinical, financial, and configuration events in your permitted scope.</p></div><span class="badge badge-light"><i class="bi bi-shield-check mr-1" aria-hidden="true"></i>Scoped view</span></div><div class="row mb-4"><div class="col-sm-6 col-xl-4 mb-3"><div class="card h-100"><div class="card-body"><div class="stat-title">Events in scope</div><div class="stat-value"><?= (int) ($summary['count'] ?? 0) ?></div><small class="text-muted">Latest 100 records</small></div></div></div><div class="col-sm-6 col-xl-4 mb-3"><div class="card h-100"><div class="card-body"><div class="stat-title">Events today</div><div class="stat-value"><?= (int) ($summary['today'] ?? 0) ?></div><small class="text-muted">Current clinic scope</small></div></div></div><div class="col-sm-6 col-xl-4 mb-3"><div class="card h-100"><div class="card-body"><div class="stat-title">Security/auth events</div><div class="stat-value text-danger"><?= (int) ($summary['security'] ?? 0) ?></div><small class="text-muted">Review for exceptions</small></div></div></div></div><div class="card"><div class="card-header"><div class="d-flex flex-wrap align-items-center justify-content-between"><div><h2 class="h5 mb-1">Event register</h2><small class="text-muted">Sanitized context is available only through the detail action.</small></div><div class="d-flex flex-wrap gap-2 mt-2 mt-md-0"><label class="sr-only" for="audit-search">Search audit events</label><input id="audit-search" class="form-control form-control-sm" type="search" placeholder="Search actions or IDs"><label class="sr-only" for="audit-date">Filter from date</label><input id="audit-date" class="form-control form-control-sm datepicker" type="text" placeholder="yyyy-mm-dd" autocomplete="off"><label class="sr-only" for="audit-action">Filter action group</label><select id="audit-action" class="custom-select custom-select-sm"><option value="">All action groups</option><option value="security">Security/auth</option><option value="billing">Billing</option><option value="prescription">Prescription</option><option value="user">Identity/access</option></select><label class="sr-only" for="audit-clinic">Filter clinic</label><input id="audit-clinic" class="form-control form-control-sm" type="number" min="1" placeholder="Clinic ID"></div></div></div><div class="table-responsive"><table class="table mb-0" id="audit-table"><thead><tr><th>Time</th><th>Action</th><th>Actor</th><th>Clinic</th><th>Correlation ID</th><th class="text-right">Details</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td data-order="<?= esc($event['occurred_at']) ?>"><?= esc($event['occurred_at']) ?></td><td><span class="badge badge-light"><?= esc($event['action']) ?></span></td><td><?= (int) $event['actor_user_id'] ?></td><td><?= (int) $event['clinic_id'] ?></td><td><code><?= esc($event['correlation_id']) ?></code></td><td class="text-right"><button class="btn btn-sm btn-outline-secondary audit-detail" type="button" data-toggle="modal" data-target="#audit-detail-modal" data-action="<?= esc($event['action'], 'attr') ?>" data-time="<?= esc($event['occurred_at'], 'attr') ?>" data-correlation="<?= esc($event['correlation_id'], 'attr') ?>" data-context="<?= esc($event['context'] ?? '', 'attr') ?>">View details</button></td></tr><?php endforeach; ?></tbody></table></div><?php if ($events === []): ?><div class="empty-state"><i class="bi bi-journal-check d-block h3 mb-2" aria-hidden="true"></i><div>No audit events found</div><small>Events will appear here when scoped actions are recorded.</small></div><?php endif; ?></div></main>
<div class="modal fade" id="audit-detail-modal" tabindex="-1" role="dialog" aria-labelledby="audit-detail-title" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-scrollable" role="document"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5" id="audit-detail-title">Audit event details</h2><button type="button" class="close" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button></div><div class="modal-body"><dl class="row mb-0"><dt class="col-sm-3">Action</dt><dd class="col-sm-9" id="audit-detail-action"></dd><dt class="col-sm-3">Time</dt><dd class="col-sm-9" id="audit-detail-time"></dd><dt class="col-sm-3">Correlation ID</dt><dd class="col-sm-9"><code id="audit-detail-correlation"></code></dd><dt class="col-sm-3">Sanitized context</dt><dd class="col-sm-9"><pre id="audit-detail-context" class="small bg-light p-3 rounded mb-0" tabindex="0"></pre></dd></dl></div></div></div></div>
<?= $this->section('scripts') ?><script>
$(function(){
  const rows = $('#audit-table tbody tr');
  function filterRows(){const search=($('#audit-search').val()||'').toLowerCase(),date=$('#audit-date').val(),action=$('#audit-action').val(),clinic=$('#audit-clinic').val(),user=$('#audit-user').val(); rows.each(function(){const row=$(this),text=row.text().toLowerCase(),time=String(row.children().eq(0).text()),group=String(row.children().eq(1).text()).toLowerCase(),actor=String(row.children().eq(2).text()),rowClinic=String(row.children().eq(3).text()); row.toggle((!search||text.indexOf(search)>=0)&&(!date||time.slice(0,10)>=date)&&(!action||group.indexOf(action)>=0)&&(!clinic||rowClinic===clinic)&&(!user||actor===user);});}
  $('#audit-clinic').after('<label class="sr-only" for="audit-user">Filter actor user</label><input id="audit-user" class="form-control form-control-sm" type="number" min="1" placeholder="Actor user ID">');
  $('#audit-search,#audit-date,#audit-action,#audit-clinic,#audit-user').on('input change',filterRows);
  $('.audit-detail').on('click',function(){const b=$(this);$('#audit-detail-action').text(b.data('action'));$('#audit-detail-time').text(b.data('time'));$('#audit-detail-correlation').text(b.data('correlation'));let context=b.attr('data-context')||'';try{context=JSON.stringify(JSON.parse(context),null,2);}catch(e){}$('#audit-detail-context').text(context||'No additional context recorded.');});
});
</script><?= $this->endSection() ?>
